"""Conversiones de unidades usadas en el curso."""

FACTOR_LIBRA_KG = 0.45359237


def libras_a_kilos(libras: float) -> float:
    return libras * FACTOR_LIBRA_KG


def kilos_a_libras(kilos: float) -> float:
    return kilos / FACTOR_LIBRA_KG


if __name__ == "__main__":
    print(libras_a_kilos(150))

from .limpieza import normalizar_sede


def total_por_sede(registros):
    totales = {}
    for sede, monto in registros:
        clave = normalizar_sede(sede)
        totales[clave] = totales.get(clave, 0) + monto
    return totales

