def c_a_f(celsius: float) -> float:
    return celsius * 9 / 5 + 32

def f_a_c(fahrenheit: float) -> float:
    return (fahrenheit - 32) * 5 / 9

if __name__ == "__main__":
    print(c_a_f(25))
    print(f_a_c(212))

import statistics

def resumen(ventas):
    return {
        "n": len(ventas),
        "media": round(statistics.mean(ventas), 2),
        "maximo": max(ventas),
    }

if __name__ == "__main__":
    print(resumen([10.0, 20.0, 30.0]))
